"""Context links reuse existing entities and decisions. Synthetic disposable MySQL only."""
import json,secrets,subprocess,requests,os
import test_contract_package as package
class OwnerWorkflow(package.ContractPackage):
 @classmethod
 def setUpClass(cls):
  super().setUpClass();r=subprocess.run([cls.f.php,str(cls.f.path/'scripts/migrate-workflow.php'),'up'],capture_output=True,text=True)
  if r.returncode:raise RuntimeError(r.stderr)
 def wget(self,route):return self.owner.get(self.base+'/order-workflow-api.php?r='+route)
 def wpost(self,**d):
  d.setdefault('request_key',secrets.token_hex(32));return self.owner.post(self.base+'/order-workflow-api.php?r=from-inquiry',json=d)
 def lead(self,max_only=False):
  d=self.f('test_01_confirmed_persistence').lead();d['name']='SYNTHETIC workflow';d['contact']='https://max.ru/u/SYNTHETIC-context' if max_only else 'workflow-'+secrets.token_hex(6)+'@example.invalid';r=requests.post(self.base+'/api.php?r=leads',json=d);self.assertEqual(r.status_code,201,r.text);return r.json()['lead_id']
 def test_inquiry_context_retries_max_contact_stale_versions_and_auth(self):
  self.prepare_synthetic_owner();lead=self.lead(True);counts=lambda:[self.f.sql('SELECT COUNT(*) n FROM '+t)[0]['n'] for t in ['nd_customers','nd_orders','nd_projects','nd_lc_order_flow']];before=counts();r=self.wpost(lead_id=lead,version=1);self.assertEqual(r.status_code,200,r.text);oid=r.json()['order_id'];self.assertEqual(counts(),[x+1 for x in before]);self.assertEqual(self.wpost(lead_id=lead,version=1).json()['order_id'],oid);self.assertEqual(counts(),[x+1 for x in before]);data=self.wget('records&order='+str(oid));self.assertEqual(data.status_code,200,data.text);self.assertIn('SYNTHETIC workflow',data.json()['context']['label']);self.assertTrue(data.json()['lists']['projects']);self.assertEqual(data.json()['flow']['commercial_state'],'INQUIRY');self.assertEqual(requests.get(self.base+'/order-workflow-api.php?r=records').status_code,401)
  new=self.lead();before=counts();self.assertEqual(self.wpost(lead_id=new,version=999).status_code,409);self.assertEqual(counts(),before)
  ready=self.wget('readiness').json()['readiness'];self.assertTrue(ready['mail']['verified']);self.assertFalse(ready['mail']['repeat_verification_required']);self.assertFalse(ready['capabilities']['public_registration']);self.assertNotIn('password',json.dumps(ready));draft=self.wget('catalog-map').json();self.assertEqual(len(draft['draft_mapping']),4);self.assertFalse(draft['publication_performed']);self.assertTrue(all(x['price'] is None and not x['approved'] for x in draft['draft_mapping']))
 def test_approved_price_applies_only_in_correct_context_and_preserves_retry(self):
  self.prepare_synthetic_owner();lead=self.lead();r=self.wpost(lead_id=lead,version=1).json();self.project_id=r['project_id'];oid=r['order_id'];project=self.owner.get(self.base+'/api.php?r=crm/projects/'+str(self.project_id)).json()['record'];updated=self.owner.patch(self.base+'/api.php?r=crm/projects/'+str(self.project_id),json={'version':int(project['version']),'description':'SYNTHETIC confirmed requirements: isolated landing page, accessible inquiry form, defined scope and explicit acceptance criteria.'});self.assertEqual(updated.status_code,200,updated.text);q=self.approved_price();version=self.f.sql('SELECT version FROM nd_orders WHERE id=?',params=[oid])[0]['version'];key=secrets.token_hex(32);data={'order_id':oid,'quotation_id':int(q['id']),'version':int(version),'confirm':True,'request_key':key};url=self.base+'/order-workflow-api.php?r=apply-price';result=self.owner.post(url,json=data);self.assertEqual(result.status_code,200,result.text);self.assertEqual(self.owner.post(url,json=data).json(),result.json());self.assertEqual(self.f.sql('SELECT total_amount FROM nd_orders WHERE id=?',params=[oid])[0]['total_amount'],result.json()['price']);self.assertEqual(self.owner.post(url,json={**data,'version':999,'request_key':secrets.token_hex(32)}).status_code,409)
 def test_named_context_controls_submit_numeric_ids_without_manual_copy(self):
  from playwright.sync_api import sync_playwright
  self.prepare_synthetic_owner();lead=self.lead();context=self.wpost(lead_id=lead,version=1).json();oid=context['order_id'];r=self.owner.post(self.base+'/api.php?r=crm/collab/projects/'+str(context['project_id'])+'/documents',json={'request_key':secrets.token_hex(32),'kind':'specification','title':'SYNTHETIC readable ready brief','fields':{'title':'SYNTHETIC ready brief','requirements':'SYNTHETIC reviewed functionality and scope','acceptance':'SYNTHETIC explicit acceptance criteria'},'file_ids':[]});revision=self.must(r)['revision'];revision=self.must(self.owner.post(self.base+'/api.php?r=crm/collab/revisions/'+str(revision['id'])+'/ready',json={'request_key':secrets.token_hex(32),'version':int(revision['version'])}))['revision']
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=browser.new_page(viewport={'width':375,'height':812});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(self.base+'/studio.php');page.locator('#password').fill(self.f.password);page.locator('#login-form button').click();page.locator('#dashboard').wait_for(state='visible');page.goto(self.base+'/order-workflow.php?order='+str(oid));page.get_by_role('heading',name='Готовность рабочего процесса',exact=True).wait_for();self.assertFalse(page.evaluate('document.documentElement.scrollWidth>innerWidth'));page.goto(self.base+'/orders.php?mode=owner&order='+str(oid));page.get_by_text('Квалифицировать обращение',exact=True).click();form=page.get_by_text('Квалифицировать обращение',exact=True).locator('..');form.locator('textarea[name=reason]').fill('SYNTHETIC qualified contextual order');form.locator('input[type=checkbox]').check();form.get_by_role('button',name='Подтвердить и сохранить').click();page.get_by_text('Зафиксировать готовый бриф',exact=True).wait_for();self.assertEqual(self.fg(oid).json()['record']['commercial_state'],'QUALIFIED');page.get_by_text('Зафиксировать готовый бриф',exact=True).click();field=page.locator('input[name=revision_id]');field.wait_for(state='hidden');select=field.locator('..').locator('select');self.assertTrue(select.is_visible());select.select_option(str(revision['id']));brief=page.get_by_text('Зафиксировать готовый бриф',exact=True).locator('..');brief.locator('textarea[name=reason]').fill('SYNTHETIC owner reviewed exact brief');brief.locator('input[type=checkbox]').check();brief.get_by_role('button',name='Подтвердить и сохранить').click();page.get_by_text('Связать одобренный расчёт',exact=True).wait_for();self.assertEqual(self.fg(oid).json()['record']['commercial_state'],'BRIEF_READY');self.assertFalse(page.evaluate('document.documentElement.scrollWidth>innerWidth'));self.assertEqual(errors,[]);browser.close()
 def test_readiness_remains_visible_when_order_records_are_unavailable(self):
  from playwright.sync_api import sync_playwright
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=browser.new_page();page.goto(self.base+'/studio.php');page.locator('#password').fill(self.f.password);page.locator('#login-form button').click();page.locator('#dashboard').wait_for(state='visible')
   page.route('**/order-workflow-api.php?r=records*',lambda route:route.fulfill(status=503,content_type='application/json',body=json.dumps({'ok':False,'detail':'SYNTHETIC preparation disabled'})))
   page.goto(self.base+'/order-workflow.php');page.get_by_role('heading',name='Готовность рабочего процесса',exact=True).wait_for();page.get_by_text('SYNTHETIC preparation disabled',exact=False).wait_for();self.assertTrue(page.get_by_text('Повторная проверка не требуется.',exact=False).is_visible());browser.close()

for name in dir(package.ContractPackage):
 if name.startswith('test_'):setattr(OwnerWorkflow,name,None)
